-- LinkML enum bdchm:HistoricalStatusEnum
DO $ddl$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE t.typname = 'historical_status_enum' AND n.nspname = current_schema()
  ) THEN
    CREATE TYPE historical_status_enum AS ENUM (
      'PRESENT',
      'ABSENT',
      'UNKNOWN',
      'HISTORICAL'
    );
  ELSE
    RAISE NOTICE 'type historical_status_enum already exists, skipping' USING ERRCODE = 'duplicate_object';
  END IF;
END
$ddl$;
ALTER TYPE historical_status_enum ADD VALUE IF NOT EXISTS 'PRESENT';
ALTER TYPE historical_status_enum ADD VALUE IF NOT EXISTS 'ABSENT';
ALTER TYPE historical_status_enum ADD VALUE IF NOT EXISTS 'UNKNOWN';
ALTER TYPE historical_status_enum ADD VALUE IF NOT EXISTS 'HISTORICAL';
COMMENT ON TYPE historical_status_enum IS 'LinkML enum bdchm:HistoricalStatusEnum. A constrained set of enumerative values indicating whether something is present, absent, historical, or its status is unknown.';

