  ) THEN
    CREATE TYPE specimen_processing_activity_type_enum AS ENUM (
      'FIXATION',
      'FREEZING',
      'MOUNTING',
      'PRESERVATION'
    );
  ELSE
    RAISE NOTICE 'type specimen_processing_activity_type_enum already exists, skipping' USING ERRCODE = 'duplicate_object';
  END IF;
END
