-- LinkML enum bdchm:QuantityOperatorEnum
DO $ddl$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE t.typname = 'quantity_operator_enum' AND n.nspname = current_schema()
  ) THEN
    CREATE TYPE quantity_operator_enum AS ENUM (
      'LESS_THAN',
      'LESS_THAN_OR_EQUAL_TO',
      'EQUAL_TO',
      'GREATER_THAN_OR_EQUAL_TO',
      'GREATER_THAN'
    );
  ELSE
    RAISE NOTICE 'type quantity_operator_enum already exists, skipping' USING ERRCODE = 'duplicate_object';
  END IF;
END
$ddl$;
ALTER TYPE quantity_operator_enum ADD VALUE IF NOT EXISTS 'LESS_THAN';
ALTER TYPE quantity_operator_enum ADD VALUE IF NOT EXISTS 'LESS_THAN_OR_EQUAL_TO';
ALTER TYPE quantity_operator_enum ADD VALUE IF NOT EXISTS 'EQUAL_TO';
ALTER TYPE quantity_operator_enum ADD VALUE IF NOT EXISTS 'GREATER_THAN_OR_EQUAL_TO';
ALTER TYPE quantity_operator_enum ADD VALUE IF NOT EXISTS 'GREATER_THAN';
COMMENT ON TYPE quantity_operator_enum IS 'LinkML enum bdchm:QuantityOperatorEnum. A constrained set of enumerative values describing operators that can be applied to a quantity.';

